import{_ as t,a as s}from"./chunks/inline-runtime-298.Fy-nlImh.js";import{_ as r,o as i,c as a,a3 as n}from"./chunks/framework.BlfGB29P.js";const h=JSON.parse('{"title":"Palette, utilisés récemment et exécution","description":"Miniatures, widgets récents enregistrés et démarrage/arrêt dans Studio 0.1.299.","frontmatter":{"title":"Palette, utilisés récemment et exécution","description":"Miniatures, widgets récents enregistrés et démarrage/arrêt dans Studio 0.1.299."},"headers":[],"relativePath":"fr/projects/grafik-visual-studio/palette-runtime.md","filePath":"fr/projects/grafik-visual-studio/palette-runtime.md","lastUpdated":1794565858000}'),o={name:"fr/projects/grafik-visual-studio/palette-runtime.md"};function l(u,e,c,d,p,m){return i(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="palette-utilises-recemment-et-execution" tabindex="-1">Palette, utilisés récemment et exécution <a class="header-anchor" href="#palette-utilises-recemment-et-execution" aria-label="Permalink to &quot;Palette, utilisés récemment et exécution&quot;">​</a></h1><p><strong>Studio 0.1.299</strong> inclut la nouvelle palette et l’exécution intégrée précédemment testée localement dans 0.1.298. <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/grafik-visual-studio-v0.1.299" target="_blank" rel="noreferrer">Mise à jour GitHub</a>.</p><h2 id="miniatures-et-descriptions" tabindex="-1">Miniatures et descriptions <a class="header-anchor" href="#miniatures-et-descriptions" aria-label="Permalink to &quot;Miniatures et descriptions&quot;">​</a></h2><p>La palette présente trois tuiles identiques par ligne : miniature en haut, nom en dessous. Les instruments utilisent leur propre rendu avec des valeurs de démonstration ; appareils et horloges utilisent des miniatures statiques originales. Les images des paquets sont conservées. Survol ou focus clavier : aperçu agrandi et courte description. Les groupes UGSo et SVG-Line/LineBox/Math affichent uniquement leur nom. Les aperçus ne commandent aucun appareil.</p><h2 id="utilises-recemment" tabindex="-1">Utilisés récemment <a class="header-anchor" href="#utilises-recemment" aria-label="Permalink to &quot;Utilisés récemment&quot;">​</a></h2><p>Le groupe <strong>Utilisés récemment</strong>, repliable indépendamment, apparaît directement sous la recherche. Il conserve jusqu’à <strong>douze types de widgets distincts</strong>, le dernier inséré en premier. Réinsérer le même type le replace en tête sans doublon. Tuiles, miniatures et descriptions correspondent à la palette normale.</p><p>Un clic insère un nouveau widget avec les valeurs par défaut du type, <strong>pas une copie du dernier widget modifié</strong>. Importer, coller depuis le presse-papiers ou simplement sélectionner un widget ne modifie pas la liste. La recherche filtre également les entrées récentes. Les types de paquets désinstallés ne sont pas proposés ; ils peuvent réapparaître après réinstallation.</p><p>Liste et état replié persistent après rechargement ou mise à jour dans le <strong>même profil de navigateur et à la même adresse web</strong>. Ils ne sont ni synchronisés entre appareils ni exportés avec les projets. Effacer les données du navigateur les réinitialise. Si le stockage est bloqué, la liste reste utilisable pendant la session. Les autres réglages et fichiers de projet restent inchangés.</p><p><img src="'+t+'" alt="Widgets récemment utilisés sur .177"></p><h2 id="execution-au-dessus-de-la-surface" tabindex="-1">Exécution au-dessus de la surface <a class="header-anchor" href="#execution-au-dessus-de-la-surface" aria-label="Permalink to &quot;Exécution au-dessus de la surface&quot;">​</a></h2><p><strong>▶</strong> près des onglets sauvegarde le projet courant puis démarre une exécution isolée au-dessus de la surface. <strong>■</strong> l’arrête. Palette, propriétés et outils d’édition, raccourcis compris, sont grisés et verrouillés. Navigation entre pages et fenêtre séparée restent accessibles. Un échec de sauvegarde empêche le démarrage.</p><p>L’arrêt restitue la page initiale de l’éditeur avec sélection, historique et défilement. La navigation de l’aperçu ne change pas la page de l’éditeur. Les widgets à onglets propres conservent leur contexte initial. Les anciens liens de mode Éditeur/Exécution sont retirés du menu ; <strong>Nouvel onglet</strong> ouvre toujours l’exécution indépendante. Les widgets d’exécution peuvent commander les appareils HA comme auparavant.</p><p><img src="'+s+'" alt="Exécution intégrée avec outils d’édition grisés"></p><h2 id="conservation-et-verification" tabindex="-1">Conservation et vérification <a class="header-anchor" href="#conservation-et-verification" aria-label="Permalink to &quot;Conservation et vérification&quot;">​</a></h2><p>Projets, types de widgets, CSS et couleurs existants conservés. Les nouvelles préférences utilisent une clé de stockage distincte. Aucun code ni illustration VIS-2 n’a été copié pour ces fonctions.</p><p>Le 8 novembre 2026, la version 0.1.299 a été vérifiée sur .177 (HA 2026.11.0/ARM64) et .193 (HA 2026.10.4/amd64) : miniatures récentes, ordre sans doublons, insertion, repli et conservation après rechargement, ainsi que verrouillage pendant la runtime intégrée. Les insertions de test ont été annulées ; les 13 et 11 widgets existants ont été conservés. Palette et démarrage/arrêt ont également été vérifiés avec sauvegarde, navigation et retour à l’éditeur. Les 23 tests JavaScript et 17 tests Python ont réussi. Détails : <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/ha_grafik_visual_studio/docs" target="_blank" rel="noreferrer">sources et rapports</a>.</p>',16)])])}const f=r(o,[["render",l]]);export{h as __pageData,f as default};
